---FreshPlayer
---刷新角色信息
---@param seqNoTxt number
---@param nameTxt string
---@param score string
---@param isMy boolean
---@param location number
function TrailMapPlayerNode:FreshPlayer(seqNoTxt, nameTxt, score, isMy, location)
    isMy = checkBool(isMy)
    self.SeqNoText.text = (checkInt(score) > 0 and tostring(seqNoTxt)) or '??'
    self.NameText.text = tostring(nameTxt)
    self.RankText.text = (checkInt(score) > 0 and tostring(math.floor(checkNumber(score)))) or localize('未评分')
    if isMy then
        KTool.SetActive(self.Effect.gameObject, true)
        local imageAlterable = KTool.GetOrAddComponent(self.BillboardNode.transform:Find("Fish").gameObject, typeof(ImageAlterable))
        if ImageAlterable then
            imageAlterable.isNativeSize = false
            imageAlterable:LoadSprite('uiatlas/trailstage/competition_main_btn_player_me.png')
        end
        --else
        --    KTool.GetOrAddComponent(self.Fish.gameObject, typeof(ImageAlterable)):LoadSprite('uiatlasl/trailstage/competition_main_btn_player_me.png')
    end
    local num = checkInt(location) % 9
    local num = math.max(1, num)
    KTool.GetOrAddComponent(self.CatImg.gameObject, typeof(ImageAlterable)):LoadSprite(string.format('uiatlas/trailstage/competition_main_ico_cat_%d.png', num))
end

function TrailMapPlayerNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailMapPlayerNode